"""ORD_LINE renumbering migration."""

from decimal import Decimal
from typing import Any


def _order_id(row: dict[str, Any]) -> str:
    """Return ORD_ID using the legacy empty-string default for missing keys."""
    return str(row.get("ORD_ID", ""))


def _line_number(row: dict[str, Any]) -> Decimal:
    """Coerce LINE_NO numerically; a missing or empty value compares as zero."""
    value = row.get("LINE_NO", "")
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and renumber surviving lines per order."""
    surviving = [
        (position, row)
        for position, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]

    surviving.sort(
        key=lambda item: (
            _order_id(item[1]),
            _line_number(item[1]),
            item[0],
        )
    )

    result: list[dict] = []
    current_order: str | None = None
    next_line_number = 0

    for _, source_row in surviving:
        order = _order_id(source_row)
        if order != current_order:
            current_order = order
            next_line_number = 1
        else:
            next_line_number += 1

        migrated_row = dict(source_row)
        migrated_row["LINE_NO"] = next_line_number
        result.append(migrated_row)

    return result
